const items = $input.all();

return items.map((item) => {
  const inputData = item.json || {};
  const searchQuery = inputData.searchQuery || 'mutuelle sante';
  const country = inputData.Country || 'FR';

  const rawLimit = inputData.resultsLimit || inputData.results_limit || inputData.ResultsLimit;
  const parsedLimit = Number.parseInt(String(rawLimit || '').trim(), 10);
  const results_limit = Number.isFinite(parsedLimit) && parsedLimit > 0
    ? Math.min(parsedLimit, 100)
    : 5;

  const baseUrl = 'https://www.facebook.com/ads/library/';
  const params = `?active_status=active&ad_type=all&country=${country}&q=${encodeURIComponent(searchQuery)}&search_type=keyword_unordered`;

  return {
    json: {
      ...inputData,
      search_query: searchQuery,
      country,
      results_limit,
      final_url: baseUrl + params
    }
  };
});

const now = new Date();
const out = [];

const isPlaceholder = (str) => typeof str === 'string' && str.includes('{{') && str.includes('}}');
const cleanText = (v) => (typeof v === 'string' ? v.trim() : '');
const normalizeForMatch = (v) => cleanText(v).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const normalizeUrl = (u) => {
  if (typeof u !== 'string') return '';
  const v = u.trim();
  if (!v) return '';
  if (!/^https?:\/\//i.test(v)) return '';
  return v;
};
const pushUnique = (arr, value) => {
  if (value && !arr.includes(value)) arr.push(value);
};

const allItems = $input.all();
for (let itemIndex = 0; itemIndex < allItems.length; itemIndex++) {
  const item = allItems[itemIndex];
  const data = item.json || {};
  const snap = data.snapshot || {};
  const cards = Array.isArray(snap.cards) ? snap.cards : [];

  const cardVariants = cards.map((card, idx) => {
    const image = normalizeUrl(card.originalImageUrl)
      || normalizeUrl(card.original_image_url)
      || normalizeUrl(card.resizedImageUrl)
      || normalizeUrl(card.resized_image_url)
      || normalizeUrl(card.videoPreviewImageUrl)
      || normalizeUrl(card.video_preview_image_url)
      || '';
    const video = normalizeUrl(card.videoHdUrl)
      || normalizeUrl(card.video_hd_url)
      || normalizeUrl(card.videoSdUrl)
      || normalizeUrl(card.video_sd_url)
      || '';

    return {
      index: idx + 1,
      title: card.title || '',
      variant_headline: card.title || '',
      body: card.body || '',
      caption: card.caption || '',
      link_description: card.linkDescription || card.link_description || '',
      link_url: card.linkUrl || card.link_url || '',
      cta_type: card.ctaType || card.cta_type || '',
      cta_text: card.ctaText || card.cta_text || '',
      original_image_url: card.originalImageUrl || card.original_image_url || '',
      resized_image_url: card.resizedImageUrl || card.resized_image_url || '',
      video_preview_image_url: card.videoPreviewImageUrl || card.video_preview_image_url || '',
      video_hd_url: card.videoHdUrl || card.video_hd_url || '',
      video_sd_url: card.videoSdUrl || card.video_sd_url || '',
      image_url: image,
      video_url: video
    };
  });

  var headline = snap.title || snap.ad_title || data.title || 'Pas de titre';
  var body_text = (snap.body && snap.body.text) || snap.ad_body || data.body || 'Pas de texte';
  var link_description = snap.linkDescription || snap.link_description || data.link_description || '';

  const is_dco_ad = isPlaceholder(headline) || isPlaceholder(body_text) || isPlaceholder(link_description);
  let is_data_from_cards = false;

  if (is_dco_ad && cardVariants.length > 0) {
    const first = cardVariants[0];
    headline = first.title || first.body || headline;
    body_text = first.body || body_text;
    link_description = first.link_description || link_description;
    is_data_from_cards = true;
  }

  const visualUrls = [];

  if (Array.isArray(snap.images)) {
    for (const img of snap.images) {
      const fromImage = normalizeUrl(img && img.originalImageUrl)
        || normalizeUrl(img && img.original_image_url)
        || normalizeUrl(img && img.resizedImageUrl)
        || normalizeUrl(img && img.resized_image_url)
        || normalizeUrl((img && img.imageCrops && img.imageCrops[0]) ? img.imageCrops[0].originalImageUrl : '')
        || normalizeUrl((img && img.image_crops && img.image_crops[0]) ? img.image_crops[0].original_image_url : '');
      pushUnique(visualUrls, fromImage);
    }
  }

  for (const v of cardVariants) pushUnique(visualUrls, v.image_url);

  if (visualUrls.length === 0) {
    const fallbackUrl = normalizeUrl(data.imageUrl)
      || normalizeUrl(data.image_url)
      || normalizeUrl((snap.cards && snap.cards[0]) ? (snap.cards[0].originalImageUrl || snap.cards[0].original_image_url) : '');
    pushUnique(visualUrls, fallbackUrl);
  }

  const has_variants = visualUrls.length > 1 || cardVariants.length > 1 || !!data.adHasMultipleVersions || !!snap.adHasMultipleVersions;
  const version_count = Math.max(visualUrls.length, cardVariants.length, data.versionCount || 0, snap.versionCount || 0, has_variants ? 2 : 1);

  let dominant_age_range = 'Unknown';
  let dominant_gender = 'All';
  let age_gender_breakdown = '';
  let eu_total_reach = 0;
  let target_locations = 'Inconnu';

  const aaa_info = (data.ad_details && data.ad_details.aaa_info) || (snap.age_country_gender_reach_breakdown ? { age_country_gender_reach_breakdown: snap.age_country_gender_reach_breakdown } : null);

  if (data.ad_details && data.ad_details.aaa_info && data.ad_details.aaa_info.location_audience) {
    target_locations = data.ad_details.aaa_info.location_audience.map(function(l) { return l.name; }).join(', ');
  }

  if (aaa_info && aaa_info.age_country_gender_reach_breakdown && aaa_info.age_country_gender_reach_breakdown.length) {
    eu_total_reach = aaa_info.eu_total_reach || 0;
    let countryData = aaa_info.age_country_gender_reach_breakdown.find(function(c) { return c.country === 'FR'; }) || aaa_info.age_country_gender_reach_breakdown[0];
    if (countryData && countryData.age_gender_breakdowns && countryData.age_gender_breakdowns.length) {
      let maxReach = 0;
      let maxGender = 'All';
      for (const b of countryData.age_gender_breakdowns) {
        const total = (b.male || 0) + (b.female || 0) + (b.unknown || 0);
        if (total > maxReach) {
          maxReach = total;
          dominant_age_range = b.age_range;
          const f = b.female || 0;
          const m = b.male || 0;
          maxGender = f > m ? 'female' : (m > f ? 'male' : 'All');
        }
      }
      dominant_gender = maxGender;
      age_gender_breakdown = countryData.age_gender_breakdowns.map(function(b) { return b.age_range + ': M=' + (b.male || 0) + ' F=' + (b.female || 0); }).join(' | ');
    }
  }

  const videoCandidates = [];
  pushUnique(videoCandidates, normalizeUrl(data.videoUrl));
  pushUnique(videoCandidates, normalizeUrl(data.video_url));
  pushUnique(videoCandidates, normalizeUrl(data.videoHdUrl));
  pushUnique(videoCandidates, normalizeUrl(data.video_hd_url));
  pushUnique(videoCandidates, normalizeUrl(data.videoSdUrl));
  pushUnique(videoCandidates, normalizeUrl(data.video_sd_url));

  if (typeof data.video_urls === 'string') {
    for (const part of data.video_urls.split(/[|,]/)) pushUnique(videoCandidates, normalizeUrl(part));
  }

  if (Array.isArray(snap.videos)) {
    for (const vid of snap.videos) {
      pushUnique(videoCandidates, normalizeUrl(vid && vid.videoHdUrl));
      pushUnique(videoCandidates, normalizeUrl(vid && vid.video_hd_url));
      pushUnique(videoCandidates, normalizeUrl(vid && vid.videoSdUrl));
      pushUnique(videoCandidates, normalizeUrl(vid && vid.video_sd_url));
      pushUnique(videoCandidates, normalizeUrl(vid && vid.url));
    }
  }

  for (const v of cardVariants) pushUnique(videoCandidates, normalizeUrl(v.video_url));

  const videoUrl = videoCandidates.find(Boolean) || '';
  const hasVideo = Boolean(videoUrl);

  const startDate = new Date(data.adRunStartDate || data.startDateFormatted || snap.creation_time || now);
  const daysActive = Math.ceil(Math.abs(now - startDate) / (1000 * 60 * 60 * 24)) || 1;

  let score = 0;
  score += Math.min(daysActive * 1.5, 30);
  score += hasVideo ? 15 : 0;
  score += (version_count || 0) * 10;
  score += Math.min((eu_total_reach || 0) / 50000, 20);

  const virality_score = Math.min(Math.round(((eu_total_reach || 0) / 100000) * 10 + (version_count * 5) + (hasVideo ? 10 : 0) + (daysActive > 30 ? 10 : 0)), 100);

  const extraTexts = (Array.isArray(snap.extraTexts) ? snap.extraTexts : [])
    .map(function(x) { return cleanText(x && x.text); })
    .filter(Boolean);

  let form_type = 'external_landing_page';
  let native_questions_array = [];
  let landing_page_intro_text = '';
  let native_landing_page_promise = '';

  if (extraTexts.length > 0) {
    const isQuestion = function(t) { return cleanText(t).endsWith('?'); };
    const isLegalText = function(t) {
      const n = normalizeForMatch(t);
      return n.includes('condition generale')
        || n.includes('conditions generales')
        || n.includes('politique de confidentialite')
        || n.includes('confidentialite')
        || n.includes('mentions legales')
        || n.includes('protection des donnees')
        || n.includes('j accepte')
        || n.includes('consentement');
    };
    const isStandardFieldLabel = function(t) {
      const n = normalizeForMatch(t);
      return [
        'full name', 'phone number', 'email', 'post code', 'postal code',
        'nom complet', 'nom', 'prenom', 'telephone', 'numero de telephone',
        'code postal', 'ville'
      ].includes(n);
    };

    const cleanedExtraTexts = extraTexts.filter(function(t) {
      return !isLegalText(t) && !isStandardFieldLabel(t);
    });

    const firstQuestionIndex = cleanedExtraTexts.findIndex(isQuestion);
    if (firstQuestionIndex > 0) {
      landing_page_intro_text = cleanedExtraTexts.slice(0, firstQuestionIndex).join(' ').trim();
    } else if (firstQuestionIndex === -1 && cleanedExtraTexts.length > 0) {
      landing_page_intro_text = cleanedExtraTexts[0];
    }

    const lastQuestionIndex = (function() {
      for (let i = cleanedExtraTexts.length - 1; i >= 0; i--) {
        if (isQuestion(cleanedExtraTexts[i])) return i;
      }
      return -1;
    })();

    const tailTexts = (lastQuestionIndex >= 0
      ? cleanedExtraTexts.slice(lastQuestionIndex + 1)
      : cleanedExtraTexts
    ).filter(function(t) { return !isQuestion(t) && cleanText(t).length > 0; });

    if (tailTexts.length > 0) {
      const longTail = tailTexts.filter(function(t) { return cleanText(t).length >= 20; });
      native_landing_page_promise = (longTail.length > 0 ? longTail[longTail.length - 1] : tailTexts[tailTexts.length - 1]).trim();
    }

    let currentQuestion = null;
    let currentChoices = [];

    for (const txt of extraTexts) {
      const lower = normalizeForMatch(txt);

      if (isLegalText(txt)) continue;

      if (txt.endsWith('?')) {
        if (currentQuestion) {
          native_questions_array.push({
            question: currentQuestion,
            type: currentChoices.length > 0 ? 'multiple_choice' : 'text',
            choices: currentChoices.length > 0 ? currentChoices : null
          });
        }
        currentQuestion = txt;
        currentChoices = [];
        continue;
      }

      if (currentQuestion && (['OUI', 'NON'].includes(txt.toUpperCase()) || txt.includes('?') || lower.includes('je ne sais pas') || /^[0-9]+.*[0-9]+$/.test(txt))) {
        currentChoices.push(txt);
        continue;
      }

      if (isStandardFieldLabel(txt)) {
        if (currentQuestion) {
          native_questions_array.push({
            question: currentQuestion,
            type: currentChoices.length > 0 ? 'multiple_choice' : 'text',
            choices: currentChoices.length > 0 ? currentChoices : null
          });
          currentQuestion = null;
          currentChoices = [];
        }
        native_questions_array.push({ question: txt, type: 'standard_field', choices: null });
      }
    }

    if (currentQuestion) {
      native_questions_array.push({
        question: currentQuestion,
        type: currentChoices.length > 0 ? 'multiple_choice' : 'text',
        choices: currentChoices.length > 0 ? currentChoices : null
      });
    }

    if (native_questions_array.length > 0) form_type = 'native_meta_form';
  }

  const parsed_form_text = native_questions_array.map(function(q) {
    if (q.type === 'multiple_choice') return '[Choix Multiple] ' + q.question + ' -> Choix: ' + ((q.choices || []).join(', '));
    if (q.type === 'standard_field') return '[Donnee Demandee] ' + q.question;
    return '[Question Ouverte] ' + q.question;
  }).join('\n');

  const questionsObject = {};
  for (let i = 0; i < 15; i++) {
    const q = native_questions_array[i];
    const k = 'question_' + (i + 1);
    if (!q) { questionsObject[k] = ''; continue; }
    if (q.type === 'multiple_choice') questionsObject[k] = '[Choix Multiple] ' + q.question + ' -> Choix: ' + ((q.choices || []).join(', '));
    else if (q.type === 'standard_field') questionsObject[k] = '[Donnee Demandee] ' + q.question;
    else questionsObject[k] = '[Question Ouverte] ' + q.question;
  }

  const variantFlat = {};
  for (let i = 0; i < 5; i++) {
    const v = cardVariants[i] || {};
    const idx = i + 1;
    variantFlat['variant_url_' + idx] = v.image_url || '';
    variantFlat['variant_title_' + idx] = v.title || '';
    variantFlat['variant_copy_' + idx] = v.body || '';
  }

  const rawAdId = data.adArchiveID || data.ad_archive_id || data.id || '';
  const pipeline_item_id = (rawAdId ? String(rawAdId) : 'noad') + '::' + String(itemIndex);

  out.push({
    json: {
      pipeline_item_id,
      ad_id: rawAdId,
      brand: data.pageName || snap.page_name || 'Inconnu',
      days_active: daysActive,
      performance_score: Math.round(score),
      headline: headline,
      body_text: body_text,
      link_description: link_description,
      ad_copy: body_text,
      visual_url: visualUrls[0] || '',
      visual_urls: visualUrls.join(' | '),
      visual_urls_json: JSON.stringify(visualUrls),
      image_count: visualUrls.length,
      has_image: visualUrls.length > 0,
      has_variants: has_variants,
      version_count: version_count,
      variant_count_from_cards: cardVariants.length,
      variant_details_json: JSON.stringify(cardVariants),
      dominant_age_range: dominant_age_range,
      dominant_gender: dominant_gender,
      age_gender_breakdown: age_gender_breakdown,
      eu_total_reach: eu_total_reach,
      target_locations: target_locations,
      is_dco_ad: is_dco_ad,
      is_data_from_cards: is_data_from_cards,
      form_type: form_type,
      form_fields_json: form_type === 'native_meta_form' ? JSON.stringify(native_questions_array) : '',
      form_total_fields: native_questions_array.length,
      native_form_questions_plain: parsed_form_text,
      landing_page_intro_text: landing_page_intro_text,
      landing_page_promise: form_type === 'native_meta_form' ? native_landing_page_promise : '',
      cta_type: data.ctaType || snap.cta_type || snap.cta_text || 'LEARN_MORE',
      video_url: videoUrl,
      has_video: hasVideo,
      website_url: snap.linkUrl || data.adSnapshotUrl || snap.link_url || data.link || snap.website_url || '',
      landing_page_url: snap.linkUrl || data.adSnapshotUrl || snap.link_url || data.link || snap.website_url || '',
      virality_score: virality_score,
      hook_type: '',
      why_it_works: '',
      takeaway_1: '',
      takeaway_2: '',
      takeaway_3: '',
      exit_hook: '',
      tunnel_friction_reasons_detailed: '',
      ...variantFlat,
      ...questionsObject
    }
  });
}

return out.sort(function(a, b) {
  return (b.json.performance_score || 0) - (a.json.performance_score || 0);
});

const items = $input.all();

const cleanText = (v) => (typeof v === 'string' ? v.trim() : '');

const inferLevel = (ctx) => {
  const levelInput = String(ctx.tunnel_friction_level || '').toLowerCase();
  if (['low', 'medium', 'high'].includes(levelInput)) return levelInput;

  const total = Number(ctx.form_total_fields ?? 0);
  const required = Number(ctx.form_required_fields ?? 0);
  const hasPhone = ctx.form_has_phone === true;

  if (total <= 4 && required <= 2 && !hasPhone) return 'low';
  if (total >= 8 || required >= 6 || (hasPhone && total >= 5)) return 'high';
  return 'medium';
};

const inferReasons = (ctx, level) => {
  const reasons = [];
  const total = Number(ctx.form_total_fields ?? 0);
  const required = Number(ctx.form_required_fields ?? 0);
  const hasPhone = ctx.form_has_phone === true;
  const hasIntro = cleanText(ctx.landing_page_intro_text).length > 0;
  const hasPromise = cleanText(ctx.landing_page_promise).length > 0;

  if (total >= 7) reasons.push('Formulaire natif trop long pour un premier contact');
  if (required >= 5) reasons.push('Trop de champs obligatoires avant la valeur percue');
  if (hasPhone) reasons.push('Demande de telephone immediate pouvant freiner les leads froids');
  if (!hasIntro) reasons.push('Absence de texte d introduction clair sur la raison du formulaire');
  if (!hasPromise) reasons.push('Promesse finale peu explicite sur le benefice du devis');

  if (reasons.length === 0 && level === 'low') {
    reasons.push('Parcours court et lisible avec effort de completion limite');
    reasons.push('Bon alignement entre promesse et soumission de formulaire');
  } else if (reasons.length === 0 && level === 'medium') {
    reasons.push('Friction moderee: structure correcte mais clarte et reassurance perfectibles');
  } else if (reasons.length === 0) {
    reasons.push('Friction elevee: effort percu important avant qualification commerciale');
  }

  return reasons.slice(0, 5).join('; ');
};

const inferRecommendations = (ctx, level) => {
  const recos = [];
  const total = Number(ctx.form_total_fields ?? 0);
  const required = Number(ctx.form_required_fields ?? 0);
  const hasPhone = ctx.form_has_phone === true;

  if (total > 5) recos.push('Reduire le formulaire a 3-5 champs pour augmenter la completion');
  if (required > 4) recos.push('Passer certains champs en optionnel et qualifier apres soumission');
  if (hasPhone) recos.push('Justifier la demande de telephone avec un benefice explicite de rappel');
  recos.push('Renforcer la reassurance pres du CTA (confidentialite, accompagnement conseiller)');
  recos.push('Rendre la promesse de sortie plus concrete: devis mutuelle rapide et personnalise');

  if (level === 'low') recos.unshift('Conserver la simplicite actuelle et tester preuve sociale locale');
  if (level === 'high') recos.unshift('Priorite haute: supprimer les champs non essentiels au premier ecran');

  return recos.slice(0, 6).join('; ');
};

const inferRate = (ctx, level) => {
  const provided = Number(ctx.tunnel_estimated_conversion_rate);
  if (Number.isFinite(provided) && provided > 0) return Math.max(0, Math.min(100, Math.round(provided)));

  let base = level === 'low' ? 38 : (level === 'medium' ? 27 : 18);
  const total = Number(ctx.form_total_fields ?? 0);
  const required = Number(ctx.form_required_fields ?? 0);
  if (total >= 8) base -= 3;
  if (required >= 6) base -= 2;
  if (!cleanText(ctx.cta_text)) base -= 2;
  return Math.max(5, Math.min(65, Math.round(base)));
};

const inferScore = (level) => {
  if (level === 'low') return 8;
  if (level === 'high') return 4;
  return 6;
};

return items.map((item) => {
  const current = item.json || {};
  const formType = current.form_type || 'external_landing_page';
  const landingPageUrl = current.landing_page_url || current.website_url || current.linkUrl || '';
  const isNative = formType === 'native_meta_form' || landingPageUrl.includes('fb.me') || landingPageUrl.includes('facebook.com/lead');

  if (isNative) {
    const nativeQuestions = (current.native_form_questions_plain || '').toLowerCase();

    const nativeCtx = {
      ...current,
      form_total_fields: current.form_total_fields ?? 0,
      form_required_fields: current.form_required_fields ?? current.form_total_fields ?? 0,
      form_has_phone: current.form_has_phone ?? (nativeQuestions.includes('phone') || nativeQuestions.includes('telephone')),
      cta_text: current.cta_text || 'Envoyer'
    };

    const level = inferLevel(nativeCtx);
    const reasons = cleanText(current.tunnel_friction_reasons) || inferReasons(nativeCtx, level);
    const recommendations = cleanText(current.tunnel_recommendations) || inferRecommendations(nativeCtx, level);
    const estimated = inferRate(nativeCtx, level);
    const score = Number(current.tunnel_quality_score);

    return {
      json: {
        ...current,
        form_type: 'native_meta_form',
        landing_page_title: current.landing_page_title || 'Formulaire natif Meta',
        landing_page_subtitle: current.landing_page_subtitle || '',
        landing_page_promise: current.landing_page_promise || current.hook_de_sortie || '',
        form_required_fields: nativeCtx.form_required_fields,
        form_optional_fields: current.form_optional_fields ?? 0,
        form_has_email: current.form_has_email ?? nativeQuestions.includes('email'),
        email_field_name: current.email_field_name || 'email',
        form_has_phone: nativeCtx.form_has_phone,
        phone_field_name: current.phone_field_name || 'phone',
        form_has_birth_date: current.form_has_birth_date ?? false,
        birth_date_field_name: current.birth_date_field_name || '',
        form_has_postal_code: current.form_has_postal_code ?? nativeQuestions.includes('post code'),
        postal_code_field_name: current.postal_code_field_name || 'postal_code',
        form_has_social_status: current.form_has_social_status ?? false,
        social_status_field_name: current.social_status_field_name || '',
        cta_text: nativeCtx.cta_text,
        estimated_completion_time: current.estimated_completion_time || '1 min',
        skip_html_fetch: true,
        tunnel_quality_score: Number.isFinite(score) && score > 0 ? score : inferScore(level),
        tunnel_friction_level: current.tunnel_friction_level || level,
        tunnel_friction_reasons: reasons,
        tunnel_recommendations: recommendations,
        tunnel_estimated_conversion_rate: estimated
      }
    };
  }

  return {
    json: {
      ...current,
      form_type: 'external_landing_page',
      landing_page_url: landingPageUrl,
      skip_html_fetch: !landingPageUrl
    }
  };
});

const currentItems = $input.all();

let checkNativeItems = [];
try {
  checkNativeItems = $('Check Native Form').all(1);
} catch (_) {
  try {
    checkNativeItems = $('Check Native Form').all();
  } catch (_) {
    checkNativeItems = [];
  }
}

const extractText = (m, fallback) => (m ? m[1].replace(/<[^>]*>?/gm, '').trim() : fallback);

return currentItems.map((item, index) => {
  const current = item.json || {};
  const pairedIndex = (item.pairedItem && typeof item.pairedItem.item === 'number') ? item.pairedItem.item : index;
  const upstream = (checkNativeItems[pairedIndex] && checkNativeItems[pairedIndex].json) ? checkNativeItems[pairedIndex].json : current;

  const rawHtml = current.data ?? current.body ?? '';
  const html = typeof rawHtml === 'string' ? rawHtml : String(rawHtml || '');

  const redirectMatch = html.match(/<a[^>]*href=["']([^"']+)["'][^>]*>\s*moved here\s*<\/a>/i);
  if (redirectMatch && redirectMatch[1]) {
    const resolvedUrl = redirectMatch[1].trim();
    return {
      json: {
        ...upstream,
        form_type: upstream.final_form_type || upstream.form_type || 'external_landing_page',
        final_form_type: upstream.final_form_type || upstream.form_type || 'external_landing_page',
        landing_page_url: resolvedUrl || upstream.landing_page_url || '',
        landing_page_title: upstream.landing_page_title || 'Redirection detectee',
        landing_page_subtitle: upstream.landing_page_subtitle || '',
        landing_page_promise: upstream.landing_page_promise || '',
        lp_parse_status: 'redirect_page_detected',
