        form_fields_json: upstream.form_fields_json || '',
        form_total_fields: upstream.form_total_fields ?? 0,
        form_required_fields: upstream.form_required_fields ?? 0,
        form_optional_fields: upstream.form_optional_fields ?? 0,
        form_has_email: upstream.form_has_email ?? false,
        email_field_name: upstream.email_field_name || '',
        form_has_phone: upstream.form_has_phone ?? false,
        phone_field_name: upstream.phone_field_name || '',
        form_has_birth_date: upstream.form_has_birth_date ?? false,
        birth_date_field_name: upstream.birth_date_field_name || '',
        form_has_postal_code: upstream.form_has_postal_code ?? false,
        postal_code_field_name: upstream.postal_code_field_name || '',
        form_has_social_status: upstream.form_has_social_status ?? false,
        social_status_field_name: upstream.social_status_field_name || '',
        cta_text: upstream.cta_text || '',
        estimated_completion_time: upstream.estimated_completion_time || ''
      }
    };
  }

  const h1Match = html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
  const h2Match = html.match(/<h2[^>]*>([\s\S]*?)<\/h2>/i);
  const pMatch = html.match(/<p[^>]*>([\s\S]*?)<\/p>/i);

  const landing_page_title = extractText(h1Match, 'Pas de titre');
  const landing_page_subtitle = extractText(h2Match, '');
  const landing_page_promise = extractText(pMatch, '').substring(0, 150);

  const formFields = [];
  for (const m of html.matchAll(/<input[^>]*>/gi)) {
    const n = (m[0].match(/name=["']([^"']*)["']/i) || [])[1];
    const t = (m[0].match(/type=["']([^"']*)["']/i) || [, 'text'])[1].toLowerCase();
    if (n && t !== 'hidden' && t !== 'submit') formFields.push({ name: n, type: t, required: /required/i.test(m[0]) });
  }
  for (const m of html.matchAll(/<select[^>]*>/gi)) {
    const n = (m[0].match(/name=["']([^"']*)["']/i) || [])[1];
    if (n) formFields.push({ name: n, type: 'select', required: /required/i.test(m[0]) });
  }

  const flags = { email: false, phone: false, birth: false, postal: false, social: false };
  const names = { email: '', phone: '', birth: '', postal: '', social: '' };

  formFields.forEach((f) => {
    const n = (f.name || '').toLowerCase();
    if (!flags.email && (n.includes('email') || f.type === 'email' || n.includes('mail'))) { flags.email = true; names.email = f.name; }
    if (!flags.phone && (n.includes('phone') || n.includes('tel') || f.type === 'tel')) { flags.phone = true; names.phone = f.name; }
    if (!flags.birth && (n.includes('birth') || n.includes('date') || n.includes('age') || n.includes('naissance'))) { flags.birth = true; names.birth = f.name; }
    if (!flags.postal && (n.includes('postal') || n.includes('code') || n.includes('zip') || n.includes('cp'))) { flags.postal = true; names.postal = f.name; }
    if (!flags.social && (n.includes('status') || n.includes('regime') || n.includes('secu') || n.includes('situation'))) { flags.social = true; names.social = f.name; }
  });

  const ctaMatch = html.match(/<button[^>]*>([\s\S]*?)<\/button>/i) || html.match(/<input[^>]*type=["']submit["'][^>]*value=["']([^"']*)["']/i);
  const final_form_type = upstream.final_form_type || upstream.form_type || 'external_landing_page';

  const requiredCount = formFields.filter((f) => f.required).length;

  return {
    json: {
      ...upstream,
      landing_page_title: upstream.landing_page_title || landing_page_title,
      landing_page_subtitle: upstream.landing_page_subtitle || landing_page_subtitle,
      landing_page_promise: upstream.landing_page_promise || landing_page_promise,
      form_type: final_form_type,
      form_fields_json: upstream.form_fields_json || JSON.stringify(formFields),
      form_total_fields: upstream.form_total_fields ?? formFields.length,
      form_required_fields: upstream.form_required_fields ?? requiredCount,
      form_optional_fields: upstream.form_optional_fields ?? (formFields.length - requiredCount),
      form_has_email: upstream.form_has_email ?? flags.email,
      email_field_name: upstream.email_field_name || names.email,
      form_has_phone: upstream.form_has_phone ?? flags.phone,
      phone_field_name: upstream.phone_field_name || names.phone,
      form_has_birth_date: upstream.form_has_birth_date ?? flags.birth,
      birth_date_field_name: upstream.birth_date_field_name || names.birth,
      form_has_postal_code: upstream.form_has_postal_code ?? flags.postal,
      postal_code_field_name: upstream.postal_code_field_name || names.postal,
      form_has_social_status: upstream.form_has_social_status ?? flags.social,
      social_status_field_name: upstream.social_status_field_name || names.social,
      cta_text: upstream.cta_text || extractText(ctaMatch, 'Envoyer'),
      estimated_completion_time: upstream.estimated_completion_time || `${Math.round(formFields.length * 0.5 + 0.5)} min`
    }
  };
});

parameters.text:
Tu es un expert senior CRO et lead generation pour la mutuelle sante en France.
Analyse le tunnel (formulaire Meta natif ou landing page externe) avec un diagnostic exploitable en acquisition.

Regles strictes:
- N'invente jamais des donnees absentes.
- Utilise les signaux disponibles, puis infere de faeon raisonnable et specifique.
- Interdit: reponses generiques, prudentes vides, ou listes vagues.
- Si une donnee manque, continue l'analyse avec hypothese prudente et utile.
- Retourne uniquement le JSON demande.

Contexte disponible:
Titre: {{ $json.landing_page_title }}
Promesse: {{ $json.landing_page_promise }}
Texte d'introduction: {{ $json.landing_page_intro_text || "N/A" }}
Type de formulaire: {{ $json.form_type }}
Champs totaux: {{ $json.form_total_fields }}
Champs obligatoires: {{ $json.form_required_fields }}
Email: {{ $json.form_has_email }}
Telephone: {{ $json.form_has_phone }}
Date de naissance: {{ $json.form_has_birth_date }}
Code postal: {{ $json.form_has_postal_code }}
Situation sociale: {{ $json.form_has_social_status }}
CTA: {{ $json.cta_text }}
Temps estime: {{ $json.estimated_completion_time }}

Methode d'evaluation obligatoire:
1) Friction de completion: volume des champs, effort pereu, sensibilite des donnees demandees.
2) Qualification commerciale: presence d'elements utiles au rappel/devis (ex: telephone) sans sur-friction.
3) Coherence conversion: pub -> promesse -> formulaire -> CTA.
4) Reassurance: credibilite, confidentialite, conformite pereue, ton rassurant marche FR.

Classification imposee pour tunnel_friction_level:
- low: parcours clair, effort faible, peu de blocages.
- medium: effort modere, quelques freins convertibles.
- high: effort eleve ou incoherences majeures, risque d'abandon fort.

Contraintes de sortie:
- tunnel_friction_reasons: 3 e 5 raisons precises liees au cas (pas de repetition).
- tunnel_recommendations: 3 e 6 actions concretes priorisees par impact.
- tunnel_estimated_conversion_rate: entier 0-100 credible.
  Reperes realistes:
  - native simple: 25-45
  - native avec friction moyenne: 15-30
  - landing externe optimisee: 12-30
  - landing externe friction forte: 5-15

Retourne UNIQUEMENT ce JSON:
{
  "tunnel_quality_score": 0,
  "tunnel_friction_level": "low|medium|high",
  "tunnel_friction_reasons": ["string"],
  "tunnel_recommendations": ["string"],
  "tunnel_estimated_conversion_rate": 0
}

parameters.jsCode:
const defaults = {
  tunnel_quality_score: 0,
  tunnel_friction_level: '',
  tunnel_friction_reasons: '',
  tunnel_recommendations: '',
  tunnel_estimated_conversion_rate: 0
};

const items = $input.all();

const safeAll = (nodeName) => {
  try { return $(nodeName).all().map((x) => x.json || {}); } catch (_) { return []; }
};

const parseSources = [
  ...safeAll('Parse Landing Page Content'),
  ...safeAll('Prepare Landing Page Extraction')
];

const byAdId = new Map();
for (const s of parseSources) {
  if (s && s.ad_id !== undefined && s.ad_id !== null && String(s.ad_id).trim() !== '') {
    byAdId.set(String(s.ad_id), s);
  }
}

const parsePossibleJson = (value) => {
  if (typeof value !== 'string') return null;
  const trimmed = value.trim();
  if (!trimmed) return null;
  try { return JSON.parse(trimmed); } catch (_) {
    const match = trimmed.match(/\{[\s\S]*\}/);
    if (!match) return null;
    try { return JSON.parse(match[0]); } catch (_) { return null; }
  }
};

const cleanText = (v) => (typeof v === 'string' ? v.trim() : '');

const toFlatText = (value) => {
  if (Array.isArray(value)) return value.map((x) => cleanText(x)).filter(Boolean).join('; ');
  return cleanText(value);
};

const inferLevel = (ctx) => {
  const levelInput = String(ctx.tunnel_friction_level || '').toLowerCase();
  if (['low', 'medium', 'high'].includes(levelInput)) return levelInput;

  const totalFields = Number(ctx.form_total_fields ?? ctx.form_required_fields ?? 0);
  const required = Number(ctx.form_required_fields ?? 0);
  const hasPhone = ctx.form_has_phone === true;
  const isNative = String(ctx.form_type || '').toLowerCase() === 'native_meta_form';

  if (totalFields <= 4 && required <= 2 && (!hasPhone || isNative)) return 'low';
  if (totalFields >= 8 || required >= 6 || (!isNative && hasPhone && totalFields >= 5)) return 'high';
  return 'medium';
};

const inferReasons = (ctx, level) => {
  const reasons = [];
  const totalFields = Number(ctx.form_total_fields ?? 0);
  const required = Number(ctx.form_required_fields ?? 0);
  const hasPhone = ctx.form_has_phone === true;
  const hasIntro = cleanText(ctx.landing_page_intro_text).length > 0;
  const hasPromise = cleanText(ctx.landing_page_promise).length > 0;
  const isNative = String(ctx.form_type || '').toLowerCase() === 'native_meta_form';

  if (totalFields >= 7) reasons.push('Formulaire long: effort de completion eleve pour un lead froid');
  if (required >= 5) reasons.push('Trop de champs obligatoires avant la proposition de valeur finale');
  if (hasPhone && !isNative) reasons.push('Demande de telephone en tunnel externe: hausse du risque d abandon precoce');
  if (!hasIntro) reasons.push('Texte d introduction faible: la raison de remplir le formulaire manque de clarte');
  if (!hasPromise) reasons.push('Promesse de sortie peu explicite: valeur immediate insuffisamment visible');

  if (reasons.length === 0 && level === 'low') {
    reasons.push('Parcours court et lisible, charge cognitive limitee pour un prospect mutuelle');
    reasons.push('CTA et promesse globalement coherents avec une logique de devis');
  }
  if (reasons.length === 0 && level === 'medium') {
    reasons.push('Friction moderee: formulaire acceptable mais perfectible sur clarte et reassurance');
    reasons.push('Quelques informations demandees trop tot par rapport a la promesse de gain');
  }
  if (reasons.length === 0 && level === 'high') {
    reasons.push('Friction elevee: effort percu trop important pour la phase de premier contact');
    reasons.push('Risque de decrochage avant soumission sans reassurance forte visible');
  }

  return reasons.slice(0, 5).join('; ');
};

const inferRecommendations = (ctx, level) => {
  const recos = [];
  const totalFields = Number(ctx.form_total_fields ?? 0);
  const required = Number(ctx.form_required_fields ?? 0);
  const hasPhone = ctx.form_has_phone === true;
  const isNative = String(ctx.form_type || '').toLowerCase() === 'native_meta_form';

  if (totalFields > 5) recos.push('Reduire le formulaire a 3-5 champs pour augmenter le taux de completion');
  if (required > 4) recos.push('Basculer une partie des champs en optionnel et qualifier apres soumission');
  if (!isNative && hasPhone) recos.push('Deplacer le telephone plus tard ou expliquer clairement l usage du rappel');
  recos.push('Renforcer la reassurance pres du CTA (confidentialite, accompagnement conseiller, transparence)');
  recos.push('Aligner explicitement pub -> promesse -> formulaire avec un benefice concret de devis mutuelle');

  if (level === 'low') recos.unshift('Conserver la simplicite actuelle et tester une variante avec preuve sociale locale');
  if (level === 'high') recos.unshift('Priorite haute: supprimer les champs non essentiels au premier ecran');

  return recos.slice(0, 6).join('; ');
};

const inferRate = (ctx, level) => {
  const provided = Number(ctx.tunnel_estimated_conversion_rate);
  if (Number.isFinite(provided) && provided > 0) return Math.max(0, Math.min(100, Math.round(provided)));

  const isNative = String(ctx.form_type || '').toLowerCase() === 'native_meta_form';
  const totalFields = Number(ctx.form_total_fields ?? 0);
  const required = Number(ctx.form_required_fields ?? 0);

  let base = 16;
  if (isNative && level === 'low') base = 38;
  else if (isNative && level === 'medium') base = 27;
  else if (isNative && level === 'high') base = 18;
  else if (!isNative && level === 'low') base = 24;
  else if (!isNative && level === 'medium') base = 16;
  else if (!isNative && level === 'high') base = 10;

  if (totalFields >= 8) base -= 3;
  if (required >= 6) base -= 2;
  if (String(ctx.cta_text || '').trim().length === 0) base -= 2;

  return Math.max(3, Math.min(65, Math.round(base)));
};

const normalize = (current, sourceHint) => {
  const context = { ...(sourceHint || {}), ...(current || {}) };
  let tunnelData = { ...defaults };
  let source = current.output ?? current;

  if (typeof source === 'string') {
    const parsed = parsePossibleJson(source);
    source = parsed || source;
  }

  if (source && typeof source === 'object' && !Array.isArray(source)) {
    tunnelData = { ...tunnelData, ...source };
  }

  let reasons = toFlatText(tunnelData.tunnel_friction_reasons);
  let recommendations = toFlatText(tunnelData.tunnel_recommendations);

  const isGenericReason = ['friction_moderee_par_defaut', 'native_form_no_friction'].includes(reasons);
  const isGenericReco = ['simplifier_formulaire_et_renforcer_reassurance', 'use_webhook_or_graph_api'].includes(recommendations);

  const level = inferLevel({ ...context, ...tunnelData });
  if (!reasons || isGenericReason) reasons = inferReasons({ ...context, ...tunnelData }, level);
  if (!recommendations || isGenericReco) recommendations = inferRecommendations({ ...context, ...tunnelData }, level);
  const estimated = inferRate({ ...context, ...tunnelData }, level);

  return {
    tunnel_quality_score: Number(tunnelData.tunnel_quality_score ?? 0) || 0,
    tunnel_friction_level: level,
    tunnel_friction_reasons: reasons,
    tunnel_recommendations: recommendations,
    tunnel_estimated_conversion_rate: estimated
  };
};

const pickSource = (item, index) => {
  const current = item.json || {};
  if (current.ad_id || current.brand || current.form_type || current.landing_page_url) return current;

  const currentOutput = current.output;
  if (currentOutput && typeof currentOutput === 'object' && !Array.isArray(currentOutput)) {
    const id = currentOutput.ad_id;
    if (id !== undefined && id !== null) {
      const key = String(id);
      if (byAdId.has(key)) return byAdId.get(key);
    }
  }

  const pairIndex = (item.pairedItem && typeof item.pairedItem.item === 'number') ? item.pairedItem.item : null;
  if (typeof pairIndex === 'number' && parseSources[pairIndex]) return parseSources[pairIndex];

  return parseSources[index] || {};
};

return items.map((item, index) => {
  const current = item.json || {};
  const source = pickSource(item, index);
  const normalized = normalize(current, source);

  return {
    json: {
      ...source,
      ...current,
      ...normalized,
      final_form_type: current.final_form_type || source.final_form_type || current.form_type || source.form_type || 'external_landing_page',
      form_type: current.form_type || source.form_type || current.final_form_type || source.final_form_type || 'external_landing_page',
      pipeline_item_id: current.pipeline_item_id || source.pipeline_item_id || '',
      ad_id: current.ad_id || source.ad_id || '',
      brand: current.brand || source.brand || '',
      landing_page_url: current.landing_page_url || source.landing_page_url || source.website_url || current.website_url || '',
      headline: current.headline || source.headline || '',
      body_text: current.body_text || source.body_text || '',
      visual_url: current.visual_url || source.visual_url || ''
    }
  };
});

