  if (typeof pairIndex === 'number' && sourcePool[pairIndex]) return sourcePool[pairIndex];
  return current;
};

const cleanText = (v) => (typeof v === 'string' ? v.trim() : '');

const collectObjects = (current) => {
  const out = [];
  const pushObj = (obj) => {
    if (obj && typeof obj === 'object' && !Array.isArray(obj)) out.push(obj);
  };

  pushObj(current.output);

  const parsedOutput = parsePossibleJson(current.output);
  if (parsedOutput) pushObj(parsedOutput);

  const parsedText = parsePossibleJson(current.text);
  if (parsedText) pushObj(parsedText);

  const parsedResp = parsePossibleJson(current.response);
  if (parsedResp) pushObj(parsedResp);

  const parsedRaw = parsePossibleJson(current.raw_text);
  if (parsedRaw) pushObj(parsedRaw);

  if (current.output && typeof current.output === 'object' && current.output.text) {
    const parsedNestedText = parsePossibleJson(current.output.text);
    if (parsedNestedText) pushObj(parsedNestedText);
  }

  return out;
};

const collectRawStrings = (current, objects) => {
  const raws = [];
  const pushRaw = (v) => {
    const t = cleanText(v);
    if (t) raws.push(t);
  };

  pushRaw(current.text);
  pushRaw(current.output);
  pushRaw(current.response);
  pushRaw(current.raw_text);
  if (current.output && typeof current.output === 'object') {
    pushRaw(current.output.text);
    pushRaw(current.output.raw_text);
  }

  for (const obj of objects) {
    pushRaw(obj.raw_text);
    pushRaw(obj.text);
  }

  return raws;
};

const extractFromRaw = (raw, key) => {
  if (!raw) return '';
  const patterns = [
    new RegExp('"' + key + '"\\s*:\\s*"([^"\\n\\r]+)"', 'i'),
    new RegExp("'" + key + "'\\s*:\\s*'([^'\\n\\r]+)'", 'i'),
    new RegExp('"' + key + '"\\s*:\\s*([\\s\\S]*?)(,|\\n|\\r|})', 'i')
  ];
  for (const re of patterns) {
    const m = raw.match(re);
    if (!m || !m[1]) continue;
    const candidate = cleanText(String(m[1]).replace(/^"|"$/g, '').replace(/^'|'$/g, ''));
    if (candidate) return candidate;
  }
  return '';
};

const pickText = (...vals) => {
  for (const v of vals) {
    const t = cleanText(v);
    if (t) return t;
  }
  return '';
};

const resolveField = (key, current, source, objects, raws) => {
  const fromObject = () => {
    for (const obj of objects) {
      const v = obj ? obj[key] : '';
      const t = cleanText(v);
      if (t) return t;
    }
    return '';
  };

  const fromRaw = () => {
    for (const raw of raws) {
      const v = extractFromRaw(raw, key);
      if (v) return v;
    }
    return '';
  };

  return pickText(
    current[key],
    fromObject(),
    fromRaw(),
    source[key]
  );
};

return items.map((item) => {
  const current = item.json || {};
  const source = pickSource(current, item);
  const objects = collectObjects(current);
  const raws = collectRawStrings(current, objects);

  const merged = {
    ...source,
    ...current,
    output: objects[0] || current.output || {},
    pipeline_item_id: current.pipeline_item_id || source.pipeline_item_id || '',
    ad_id: current.ad_id || source.ad_id || ''
  };

  const fields = ['hook_type', 'why_it_works', 'takeaway_1', 'takeaway_2', 'takeaway_3', 'hook_de_sortie', 'tunnel_friction_reasons', 'tunnel_recommendations'];
  for (const key of fields) {
    const value = resolveField(key, current, source, objects, raws);
    if (value) merged[key] = value;
  }

  return { json: merged };
});

return $input.all().map((item) => {
  const binaryData = item.binary.data;

  if (!binaryData) {
    return { json: item.json || {} };
  }

  return {
    json: item.json || {},
