const items = $input.all();

const num = (v, d = 0) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : d;
};

const txt = (v) => (typeof v === 'string' ? v.trim() : '');
const clamp = (v, min, max) => Math.max(min, Math.min(max, v));

const parseJsonArray = (value) => {
  if (typeof value !== 'string') return [];
  const t = value.trim();
  if (!t) return [];
  try {
    const parsed = JSON.parse(t);
    return Array.isArray(parsed) ? parsed : [];
  } catch (_) {
    return [];
  }
};

const countQualificationQuestions = (j) => {
  const fromJson = parseJsonArray(j.form_fields_json).filter((q) => q && q.type && q.type !== 'standard_field').length;
  if (fromJson > 0) return fromJson;

  const plain = txt(j.native_form_questions_plain).split('\n').map((x) => x.trim()).filter(Boolean);
  return plain.filter((line) => line.startsWith('[Choix Multiple]') || line.startsWith('[Question Ouverte]')).length;
};

const hasNameSignal = (j) => {
  const plain = txt(j.native_form_questions_plain).toLowerCase();
  return plain.includes('full name') || plain.includes('nom') || plain.includes('prenom') || plain.includes('name');
};

const buildReason = (parts) => parts.filter(Boolean).join(' | ');

return items.map((item) => {
  const j = item.json || {};
  const formType = (j.final_form_type || j.form_type || '').toLowerCase();
  const isNative = formType === 'native_meta_form';

  const days = num(j.days_active);
  const reach = num(j.eu_total_reach);
  const perf = clamp(num(j.performance_score), 0, 100);

  const daysScore = clamp((days / 45) * 100, 0, 100);
  const reachScore = clamp((Math.log10(reach + 1) / 6) * 100, 0, 100);
  const tractionScore = Math.round(clamp(0.35 * daysScore + 0.35 * reachScore + 0.30 * perf, 0, 100));

  const variantCount = Math.max(
    num(j.variant_count),
    num(j.variant_count_from_cards),
    num(j.version_count),
    num(j.image_count > 1 ? j.image_count : 0)
  );
  const hasVariants = j.has_variants === true || variantCount > 1;
  const scalingScore = Math.round(clamp((variantCount * 10) + (hasVariants ? 20 : 0) + (days >= 30 ? 20 : 0) + (reach >= 50000 ? 20 : 0), 0, 100));

  const tunnelQualityRaw = num(j.tunnel_quality_score);
  const tunnelQualityScore = tunnelQualityRaw <= 10 ? tunnelQualityRaw * 10 : clamp(tunnelQualityRaw, 0, 100);
  const friction = (txt(j.tunnel_friction_level).toLowerCase() || 'medium');
  const frictionAdj = friction === 'low' ? 10 : (friction === 'high' ? -15 : 0);
  const convRate = clamp(num(j.tunnel_estimated_conversion_rate), 0, 100);
  const tunnelScore = Math.round(clamp((0.6 * tunnelQualityScore) + (0.4 * convRate) + frictionAdj, 0, 100));

  const hook = txt(j.hook_type);
  const why = txt(j.why_it_works);
  const takeaways = [txt(j.takeaway_1), txt(j.takeaway_2), txt(j.takeaway_3)].filter(Boolean).length;
  const creativeScore = Math.round(clamp((hook ? 20 : 0) + (why ? 35 : 0) + (takeaways * 15) + (txt(j.headline) ? 10 : 0) + (txt(j.body_text) ? 10 : 0), 0, 100));

  const hasPhone = j.form_has_phone === true;
  const hasPostal = j.form_has_postal_code === true;
  const hasEmail = j.form_has_email === true;
  const hasName = hasNameSignal(j);
  const qualCount = countQualificationQuestions(j);

  let leadQualityScore = 0;
  if (isNative) {
    leadQualityScore += hasName ? 15 : 5;
    leadQualityScore += hasPhone ? 35 : 0;
    leadQualityScore += hasPostal ? 25 : 0;
    leadQualityScore += hasEmail ? 10 : 0;
    leadQualityScore += Math.min(qualCount, 3) * 5;
    if (!hasPhone || !hasPostal) leadQualityScore = Math.min(leadQualityScore, 49);
  } else {
    leadQualityScore = 40;
    if (txt(j.landing_page_url)) leadQualityScore += 8;
    if (convRate >= 20) leadQualityScore += 10;
    if (tunnelQualityScore >= 60) leadQualityScore += 10;
    if (txt(j.cta_text)) leadQualityScore += 5;
    leadQualityScore = Math.min(leadQualityScore, 75);
  }
  leadQualityScore = Math.round(clamp(leadQualityScore, 0, 100));

  const leadQualityLevel = leadQualityScore >= 75 ? 'HIGH' : (leadQualityScore >= 55 ? 'MEDIUM' : 'LOW');

  const winnerScore = Math.round(clamp(
    isNative
      ? (0.20 * tractionScore) + (0.15 * scalingScore) + (0.35 * leadQualityScore) + (0.20 * tunnelScore) + (0.10 * creativeScore)
      : (0.25 * tractionScore) + (0.20 * scalingScore) + (0.10 * leadQualityScore) + (0.25 * tunnelScore) + (0.20 * creativeScore),
    0,
    100
  ));

  let winnerStatus = 'LOSER';
  let winnerReason = '';

  if (isNative && (!hasPhone || !hasPostal)) {
    winnerStatus = 'LOSER';
    winnerReason = 'Lead minimum non vendable: telephone et code postal obligatoires manquants.';
  } else {
    const winThreshold = isNative ? 72 : 78;
    const testThreshold = isNative ? 55 : 58;

    if (winnerScore >= winThreshold) winnerStatus = 'WINNER';
    else if (winnerScore >= testThreshold) winnerStatus = 'TEST';
    else winnerStatus = 'LOSER';

    winnerReason = buildReason([
      `Traction=${tractionScore}`,
      `Scaling=${scalingScore}`,
      `LeadQuality=${leadQualityScore}`,
      `Tunnel=${tunnelScore}`,
      `Creative=${creativeScore}`,
      isNative ? `NativeMinLead=${hasPhone && hasPostal ? 'OK' : 'KO'}` : 'External=Evaluation prudente'
    ]);
  }

  let scalingRecommendation = '';
  if (winnerStatus === 'WINNER') {
    if (scalingScore >= 65) {
      scalingRecommendation = 'Scaler progressivement (+20-30%) et dupliquer les meilleures variantes/copies.';
    } else {
      scalingRecommendation = 'Confirmer la stabilite 3-5 jours puis lancer nouveaux tests de variantes.';
    }
  } else if (winnerStatus === 'TEST') {
    scalingRecommendation = isNative
      ? 'Conserver en test: optimiser qualification (questions utiles) et clarte promesse avant scale.'
      : 'Conserver en test prudent: verifier qualite lead reelle avant augmentation budget.';
  } else {
    scalingRecommendation = isNative
      ? 'Revoir le formulaire natif (telephone + code postal + qualification utile) avant retest.'
      : 'Revoir angle/tunnel externe avant nouveau test budget.';
  }

  const variantDetails = parseJsonArray(j.variant_details_json);
  const firstUsableVariant = variantDetails.find((v) => {
    if (!v || typeof v !== 'object') return false;
    return Boolean(
      txt(v.variant_headline || v.title)
      || txt(v.body)
      || txt(v.original_image_url || v.image_url || v.resized_image_url || v.video_preview_image_url)
      || txt(v.video_hd_url || v.video_sd_url || v.video_url)
    );
  });

  const variantPreview = firstUsableVariant
    ? [
        txt(firstUsableVariant.variant_headline || firstUsableVariant.title),
        txt(firstUsableVariant.body),
        txt(firstUsableVariant.original_image_url || firstUsableVariant.image_url || firstUsableVariant.resized_image_url || firstUsableVariant.video_preview_image_url),
        txt(firstUsableVariant.video_hd_url || firstUsableVariant.video_sd_url || firstUsableVariant.video_url)
      ].filter(Boolean).join(' | ')
    : '';

  const adPreview = [
    txt(j.headline || j.variant_title_1),
    txt(j.body_text || j.ad_copy || j.variant_copy_1),
    txt(j.visual_url || j.variant_url_1),
    txt(j.video_url)
  ].filter(Boolean).join(' | ');

  const bestVariantPreview = variantPreview || adPreview;

  return {
    json: {
      ...j,
      variant_count: variantCount,
      lead_quality_score: leadQualityScore,
      lead_quality_level: leadQualityLevel,
      winner_score: winnerScore,
      winner_status: winnerStatus,
      winner_reason: winnerReason,
      scaling_recommendation: scalingRecommendation,
      best_variant_preview: bestVariantPreview
    }
  };
});

const winners = $input.all().map(i => i.json || {})
  .filter((j) => String(j.winner_status || '').toUpperCase() === 'WINNER');

winners.sort((a, b) => {
  const byScore = Number(b.winner_score || 0) - Number(a.winner_score || 0);
  if (byScore !== 0) return byScore;
  return Number(b.lead_quality_score || 0) - Number(a.lead_quality_score || 0);
});

return winners.slice(0, 3).map((j, idx) => ({
  json: {
    ...j,
    priority_rank: idx + 1
  }
}));

