const items = $input.all();
const out = [];

const parsePossibleJson = (value) => {
  if (typeof value !== 'string') return null;
  const t = value.trim();
  if (!t) return null;
  try { return JSON.parse(t); } catch (_) {
    const m = t.match(/\{[\s\S]*\}/);
    if (!m) return null;
    try { return JSON.parse(m[0]); } catch (_) { return null; }
  }
};

const txt = (v) => (typeof v === 'string' ? v.trim() : '');

const safeAll = (nodeName) => {
  try { return $(nodeName).all().map((x) => x.json || {}); } catch (_) { return []; }
};

const parentPool = safeAll('Keep Top 3 Winners');
const byAdId = new Map();
const byPipeline = new Map();
for (const p of parentPool) {
  if (p && p.ad_id !== undefined && p.ad_id !== null && String(p.ad_id).trim() !== '') byAdId.set(String(p.ad_id), p);
  if (p && p.pipeline_item_id) byPipeline.set(String(p.pipeline_item_id), p);
}

const pickParent = (current, item, index) => {
  if (current && current.pipeline_item_id && byPipeline.has(String(current.pipeline_item_id))) return byPipeline.get(String(current.pipeline_item_id));
  if (current && current.ad_id !== undefined && current.ad_id !== null && byAdId.has(String(current.ad_id))) return byAdId.get(String(current.ad_id));

  const pairIndex = (item.pairedItem && typeof item.pairedItem.item === 'number') ? item.pairedItem.item : index;
  if (typeof pairIndex === 'number' && parentPool[pairIndex]) return parentPool[pairIndex];

  return current || {};
};

const fallbackTakeaway = (idx) => {
  if (idx === 1) return 'Mettre une promesse claire avec benefice chiffre dans les 2 premieres lignes.';
  if (idx === 2) return 'Rendre le visuel lisible mobile avec un seul message principal et un CTA explicite.';
  return 'Aligner angle, hook et formulaire pour maximiser la qualite des leads.';
};

for (let index = 0; index < items.length; index++) {
  const item = items[index];
  const j = item.json || {};
  const parent = pickParent(j, item, index);

  const parsed =
    (j.output && typeof j.output === 'object' ? j.output : null)
    || parsePossibleJson(j.output)
    || parsePossibleJson(j.text)
    || parsePossibleJson(j.response)
    || null;

  const creative = (parsed && parsed.creative_output) ? parsed.creative_output : (j.creative_output || {});
  const ads = Array.isArray(creative.ads) ? creative.ads : [];
  const angles = Array.isArray(creative.angles) ? creative.angles : [];
  const fr = creative.form_recommendation || {};

  const adsToUse = ads.length > 0 ? ads : [{
    angle: angles[0] || parent.hook_type || 'Angle economie',
    hook: parent.hook_type || 'benefice_direct',
    primary_text: parent.body_text || parent.ad_copy || '',
    headline: parent.headline || '',
    cta: 'Obtenir mon devis',
    rationale: parent.why_it_works || parent.winner_reason || 'Positionnement orient? devis mutuelle simple et rassurant.',
    visual_angle: 'Temoignage + economie',
    visual_concept: 'Couple senior rassure avec simulation de devis',
    image_prompt: 'Photo realiste style publicite mutuelle sante france, couple senior, ambiance rassurante, callout economies, format 1:1',
    image_text_overlay: 'Jusqu a 300EUR d economies / an',
    design_notes: 'Contraste fort, logo visible, CTA lisible',
    video_angle: 'Devis rapide et rassurance',
    video_hook: 'Et si vous payiez moins pour mieux rembourser?',
    video_script: 'Hook + probleme + solution + preuve + CTA',
    video_scenes: ['Hook visuel', 'Comparaison avant/apres', 'CTA devis'],
    video_text_overlay: 'Devis en 30 sec',
    video_cta: 'Verifier mes economies',
    video_creation_prompt: 'Video UGC style courtier mutuelle france, 20 secondes, ton rassurant'
  }];

  // 3 winners x max 2 creatives = 3 a 6 creatives au total
  const limitedAds = adsToUse.slice(0, 2);

  for (let i = 0; i < limitedAds.length; i++) {
    const ad = limitedAds[i] || {};
    const creative_index = i + 1;
    const adBaseId = String(parent.ad_id || j.ad_id || 'no_ad_id');
    const creative_id = `${adBaseId}_${creative_index}_${Date.now()}_${Math.floor(Math.random() * 10000)}`;

    const imagePrompt = txt(ad.image_prompt);
    const generatedImageUrl = imagePrompt
      ? `https://image.pollinations.ai/prompt/${encodeURIComponent(imagePrompt)}?width=1024&height=1024&nologo=true`
      : '';

    const hasImage = Boolean(txt(parent.visual_url) || imagePrompt || txt(ad.visual_concept));
    const hasVideo = Boolean(txt(parent.video_url) || txt(ad.video_creation_prompt) || txt(ad.video_script));
    const visualType = hasImage && hasVideo ? 'image+video' : (hasVideo ? 'video' : 'image');

    const hookType = txt(parent.hook_type) || txt(ad.hook) || 'benefice_direct';
    const whyItWorks = txt(parent.why_it_works) || txt(ad.rationale) || `Promesse claire orientee ${txt(parent.form_type || parent.final_form_type || 'leadgen')} avec benefice concret.`;
    const takeaway1 = txt(parent.takeaway_1) || fallbackTakeaway(1);
    const takeaway2 = txt(parent.takeaway_2) || fallbackTakeaway(2);
    const takeaway3 = txt(parent.takeaway_3) || fallbackTakeaway(3);

    const inspirationSource = txt(parent.best_variant_preview) || txt(parent.variant_details_json) ? 'variant' : 'ad';

    out.push({
