        takeaway_1: takeaway1,
        takeaway_2: takeaway2,
        takeaway_3: takeaway3,
        angle_marketing: txt(ad.angle),
        visual_type: visualType,
        inspiration_source: inspirationSource,
        angle: txt(ad.angle),
        hook: txt(ad.hook),
        primary_text: txt(ad.primary_text),
        headline: txt(ad.headline),
        cta: txt(ad.cta),
        rationale: txt(ad.rationale),
        visual_angle: txt(ad.visual_angle),
        visual_concept: txt(ad.visual_concept),
        image_prompt: imagePrompt,
        image_text_overlay: txt(ad.image_text_overlay),
        design_notes: txt(ad.design_notes),
        generated_image_url: generatedImageUrl,
        video_angle: txt(ad.video_angle),
        video_hook: txt(ad.video_hook),
        video_script: txt(ad.video_script),
        video_scenes: Array.isArray(ad.video_scenes) ? ad.video_scenes.join(' | ') : txt(ad.video_scenes),
        video_text_overlay: txt(ad.video_text_overlay),
        video_cta: txt(ad.video_cta),
        video_creation_prompt: txt(ad.video_creation_prompt),
        required_fields: Array.isArray(fr.required_fields) ? fr.required_fields.join(' | ') : txt(fr.required_fields),
        optional_fields: Array.isArray(fr.optional_fields) ? fr.optional_fields.join(' | ') : txt(fr.optional_fields),
        qualification_fields: Array.isArray(fr.qualification_fields) ? fr.qualification_fields.join(' | ') : txt(fr.qualification_fields)
      }
    });
  }
}

return out;
